582	                }
583	                (Token::Operation('~'), span) => {
584	                    ops.push((UnaryOp::BitwiseNot, span));
585	                }
586	                (Token::Operation('*'), span) => {
587	                    ops.push((UnaryOp::Deref, span));
588	                }
589	                (Token::Operation('&'), span) => {
590	                    ops.push((UnaryOp::AddrOf, span));
