645	                }
646	                (Token::Operation('&'), _) => {
647	                    let expr =
648	                        this.lhs_expression(lexer, ctx, None, ExpectedToken::LhsExpression)?;
649	                    let expr = ast::Expression::AddrOf(expr);
650	                    let span = this.peek_rule_span(lexer);
